            <g class="edgemap__pings"><circle r="3.5"><animateMotion dur="2.2s" repeatCount="indefinite"><mpath href="#el-1"/></animateMotion></circle><circle r="3.5"><animateMotion dur="2.6s" begin=".4s" repeatCount="indefinite"><mpath href="#el-2"/></animateMotion></circle><circle r="3.5"><animateMotion dur="2s" begin=".8s" repeatCount="indefinite"><mpath href="#el-3"/></animateMotion></circle><circle r="3.5"><animateMotion dur="2.4s" begin="1.2s" repeatCount="indefinite"><mpath href="#el-4"/></animateMotion></circle></g>
            <g class="edgemap__nodes"><circle class="hubc" cx="180" cy="125" r="13"/><g data-site="Site north · healthy"><circle cx="80" cy="76" r="8"/><circle class="ring" cx="80" cy="76" r="8"/></g><g data-site="Site east · healthy"><circle cx="290" cy="82" r="8"/><circle class="ring" cx="290" cy="82" r="8"/></g><g data-site="Site south-west · one warning"><circle class="warn" cx="96" cy="196" r="8"/><circle class="ring" cx="96" cy="196" r="8"/></g><g data-site="Site south-east · healthy"><circle cx="282" cy="192" r="8"/><circle class="ring" cx="282" cy="192" r="8"/></g></g>
