<!-- ============ 5. Why teams move (comparison + pillars) ============ -->
<section class="sec" id="compare" aria-labelledby="compare-title">
  <div class="wrap">
    <div class="sec-head sec-head--split rv">
      <div>
        <p class="eyebrow">Why teams move</p>
